import {SCHOOLS} from './data.js';
import {overall} from './growth.js';
import {random,clamp} from './random.js';
export const mayEnterUniversity=s=>s.stage==='high'&&!s.teams.some(t=>['university','overseas'].includes(t.stage));
export function schoolScouting(s){if(s.stage!=='middle')return;const ability=overall(s);const visibility=s.environmentId==='club'?1.12:s.environmentId==='school'?.85:s.environmentId==='academy'?.92:1.05;for(const school of SCHOOLS.filter(c=>c.active!==false)){if(s.schoolOffers.some(o=>o.id===school.id))continue;const world=s.nationalHistory.filter(n=>n.selected&&['u12','u15'].includes(n.cupId));const achievement=Math.min(12,world.reduce((v,n)=>v+(n.result==='優勝'?7:n.result==='準優勝'?5:3),0));const threshold=school.competition*.6+12-achievement;if(ability<threshold)continue;if(random(s)<clamp((.2+(ability-threshold)*.025)*visibility,.15,.9)){s.schoolOffers.push({id:school.id,year:s.year,ability});s.scoutPopup=true;s.timeline.push({year:s.year,text:school.name+'から推薦の誘い。能力・年代別代表実績を評価される'});s.news.push(school.name+'のスカウトが視察。推薦のオファーが届いた。');}}}
export function schoolOutlook(s,c){const recruited=s.schoolOffers?.some(o=>o.id===c.id);const chance=clamp(c.national+(overall(s)-c.competition)*.003,.015,.85);const opportunity=clamp(c.opportunity+(overall(s)-c.competition)*.012+(recruited?.1:0),.25,1.1);return {recruited,chance:Math.round(chance*100),opportunity:Math.round(Math.min(1,opportunity)*100)};}
